reqs=[];metas=[]
for _ in range(4000):
    P=random.randint(1,2);R=random.randint(1,2);D=random.randint(0,2)
    inputs=[[[random.randint(-2,2) for _ in range(D)] for _ in range(R)] for _ in range(P)]
    n=random.randint(1,7)
    exp,_,_,_=expected_sums(inputs)
    states=[]
    for i in range(n):
        delivered=[]
        for r in range(P):
            ln=random.randint(0,R)
            arr=[list(exp[q]) if random.random()<0.85 else [random.randint(-4,4) for _ in range(D)] for q in range(ln)]
            delivered.append(arr)
        slots=[];used=set()
        for _ in range(random.randint(0,min(2,R))):
            sq=random.randint(0,R-1)
            if sq in used:continue
            used.add(sq)
            ranks=sorted(random.sample(range(P),random.randint(0,P)))
            acc=[0]*D
            for rr in ranks:
                for d in range(D):acc[d]+=inputs[rr][sq][d]
            if random.random()<0.85:sm=acc
            else:sm=[random.randint(-4,4) for _ in range(D)]
            slots.append({"seq":sq,"ranks":ranks,"sum":sm})
